import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    a = [int(data[i]) for i in range(3)]

    min_cost = float('inf')
    for i in range(3):
        for j in range(3):
            if i == j:
                continue
            for k in range(3):
                if k == i or k == j:
                    continue
                cost = abs(a[j] - a[i]) + abs(a[k] - a[j])
                min_cost = min(min_cost, cost)
    print(min_cost)

if __name__ == "__main__":
    solve()
